file:write.file:content:
#[%dw 2.0 output application/octet-stream
var rows = vars.recordsToWrite map ((record) -> { SKU: record.SKU, StoreId: record.StoreId, Type: record.Type, Quantity: record.Quantity, Timestamp: record.Timestamp })
--- write( rows, "application/csv", { header: not (vars.localFileExists default false), separator: ",", quoteValues: true, lineSeparator: "\n" } )]
